sys_script.script:
/**
 * ESR - Manage lifecycle timestamps
 * Before / Update / Order 300
 *
 * Handles:
 * 1. Resolved lifecycle timestamps
 * 2. Closed lifecycle timestamps
 * 3. Reopening from Resolved OR Closed
 * 4. Reopen count increment
 * 5. Active status
 * 6. Clearing stale lifecycle values
 * 7. State-change audit work notes
 *
 * No current.update() is used.
 */

(function manageLifecycleTimestamps(current, previous) {

    // Only execute on updates
    if (!previous) {
        return;
    }

    var state = current.getValue('state');
    var previousState = previous.getValue('state');

    // Only run when state actually changes
    if (state === previousState) {
        return;
    }

    var utils = new x_412993_employe_1.EsrTicketUtils();

    var nowValue = new GlideDateTime().getValue();
    var userId = gs.getUserID();

    var STATE_LABELS = {
        '1': 'New',
        '2': 'Assigned',
        '3': 'In Progress',
        '4': 'On Hold',
        '5': 'Resolved',
        '6': 'Closed'
    };

    var fromLabel = STATE_LABELS[previousState] || previousState || 'Unknown';
    var toLabel = STATE_LABELS[state] || state || 'Unknown';

    var audit = 'State changed from ' + fromLabel + ' to ' + toLabel + '.';


    /* ==========================================================
       ENTERING RESOLVED (5)
       ========================================================== */

    if (state === '5') {

        current.setValue('resolved_at', nowValue);
        current.setValue('resolved_by', userId);

        current.setValue(
            'resolution_hours',
            utils.hoursBetween(
                current.getValue('opened_at'),
                nowValue
            )
        );

        current.setValue('active', false);

        var resolutionCode = current.getDisplayValue('resolution_code');

        if (resolutionCode) {
            audit += ' Resolution code: ' + resolutionCode + '.';
        }
    }


    /* ==========================================================
       ENTERING CLOSED (6)
       ========================================================== */

    if (state === '6') {

        current.setValue('closed_at', nowValue);
        current.setValue('closed_by', userId);

        current.setValue('active', false);
    }


    /* ==========================================================
       REOPENING
       Supports:
       Resolved (5) -> In Progress (3)
       Closed (6)   -> In Progress (3)
       ========================================================== */

    var isReopening =
        (previousState === '5' || previousState === '6') &&
        state === '3';

    if (isReopening) {

        // Clear previous resolution details
        current.setValue('resolved_at', '');
        current.setValue('resolved_by', '');
        current.setValue('resolution_hours', '');

        // Clear previous closure details
        current.setValue('closed_at', '');
        current.setValue('closed_by', '');

        // Stamp the reopen date/time
        current.setValue('reopened_at', nowValue);

        // Increment reopen counter
        var reopenCount = parseInt(
            current.getValue('reopen_count'),
            10
        );

        if (isNaN(reopenCount) || reopenCount < 0) {
            reopenCount = 0;
        }

        current.setValue(
            'reopen_count',
            reopenCount + 1
        );

        // Make ticket active again
        current.setValue('active', true);

        // Clear previous hold reason
        current.setValue('on_hold_reason', '');

        // Add reopen reason to audit
        var reopenReason = current.getValue('reopen_reason');

        if (reopenReason) {
            audit += ' Reopen reason: ' + reopenReason + '.';
        }
    }


    /* ==========================================================
       OPEN STATES (1, 2, 3, 4)
       ========================================================== */

    if (
        state === '1' ||
        state === '2' ||
        state === '3' ||
        state === '4'
    ) {

        current.setValue('active', true);

        // Clear old closure information
        current.setValue('closed_at', '');
        current.setValue('closed_by', '');
    }


    /* ==========================================================
       LEAVING ON HOLD
       ========================================================== */

    if (previousState === '4' && state !== '4') {

        current.setValue('on_hold_reason', '');
    }


    /* ==========================================================
       AUDIT TRAIL
       ========================================================== */

    current.setValue('work_notes', audit);


})(current, previous);
